import java.util.*;

public class DailyTemperatures {
    public int[] dailyTemperatures(int[] temperatures) {
        int n = temperatures.length;
        int[] answer = new int[n];
        Deque<Integer> stack = new ArrayDeque<>(); // 存索引，栈底→栈顶温度递减

        for (int i = 0; i < n; i++) {
            // 当前温度高于栈顶对应温度 → 栈顶等到了答案
            while (!stack.isEmpty() && temperatures[i] > temperatures[stack.peek()]) {
                int j = stack.pop();
                answer[j] = i - j; // 等待天数 = 两个索引之差
            }
            stack.push(i); // 当前天入栈，等待未来更高温度
        }
        // 栈中剩余元素：右边没有更高温度，answer 保持默认 0
        return answer;
    }
}

import java.util.*;

public class DailyTemperaturesCircular {
    public int[] dailyTemperatures(int[] temperatures) {
        int n = temperatures.length;
        int[] answer = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();

        // 遍历 2n 个位置，索引用 i % n 取模
        for (int i = 0; i < 2 * n; i++) {
            int idx = i % n;
            while (!stack.isEmpty() && temperatures[idx] > temperatures[stack.peek()]) {
                int j = stack.pop();
                answer[j] = i - j; // i - j 可能 > n，但语义正确
            }
            // 只在第一轮入栈（避免同一索引入栈两次）
            if (i < n) {
                stack.push(idx);
            }
        }
        return answer;
    }
}
